다음 C 코드의 실행 결과는? (재귀와 배열)

#include <stdio.h>
int sum(int arr[], int n) {
    if (n == 0) return 0;
    return arr[n - 1] + sum(arr, n - 1);
}
int main() {
    int arr[5] = {1, 2, 3, 4, 5};
    printf("%d", sum(arr, 5));
    return 0;
}

