다음 C 코드의 실행 결과는? (while과 포인터 순회)

#include <stdio.h>
int main() {
    char str[] = "abc";
    char *p = str;
    int count = 0;
    while (*p != '\0') {
        count++;
        p++;
    }
    printf("%d", count);
    return 0;
}
